import sys

class Calculator:
    def add(self, a, b):
        return a + b
    def sub(self, a, b):
        return a - b

calc = Calculator()
for line in sys.stdin:
    parts = line.split()
    if len(parts) == 3:
        op, a, b = parts[0], int(parts[1]), int(parts[2])
        if op == 'add':
            print(calc.add(a, b))
        elif op == 'sub':
            print(calc.sub(a, b))
